package com.nihongo.staff.controller;
import com.nihongo.staff.repository.ContentOperationAuditRepository;import com.nihongo.security.SafeCsv;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.http.*;import org.springframework.data.domain.PageRequest;import java.util.*;
@RestController @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')")
public class ContentAuditExportController {
 private final ContentOperationAuditRepository audit;
 @GetMapping("/api/staff/content/audit/operations/export") public ResponseEntity<byte[]> export(@RequestParam(required=false) java.time.LocalDate from,@RequestParam(required=false) java.time.LocalDate to){var dates=com.nihongo.security.CsvDates.validate(from,to);var records=audit.findByCreatedAtGreaterThanEqualAndCreatedAtLessThanOrderByCreatedAtDescIdDesc(dates.from().atStartOfDay(),dates.to().plusDays(1).atStartOfDay(),PageRequest.of(0,10000));if(records.getTotalElements()>10000)throw new org.springframework.web.server.ResponseStatusException(HttpStatus.BAD_REQUEST,"Nhật ký vượt 10000 dòng");var rows=records.getContent().stream().map(a->Arrays.asList(a.getCreatedAt(),a.getActor(),a.getAction(),a.getTarget(),a.getDetail())).toList();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=content-audit.csv").contentType(MediaType.parseMediaType("text/csv;charset=UTF-8")).body(SafeCsv.write(List.of("Thời gian","Người thao tác","Hành động","Đối tượng","Chi tiết"),rows));}
}
